        void SensitivityTab()
        {
            Heading("PRODUCTION STAT SENSITIVITY");EditorGUILayout.HelpBox("Absolute inputs are flat points or fraction-of-one percentage points according to the selected stat. Relative inputs scale the current measured stat; a zero baseline uses a one-unit reference. Analytical mode evaluates the production build; combat mode uses common fight seeds.",MessageType.Info);
            sensitivity.mode=(SensitivityMode)EditorGUILayout.EnumPopup("Mode",sensitivity.mode);sensitivity.perturbation=(PerturbationMode)EditorGUILayout.EnumPopup("Change",sensitivity.perturbation);sensitivity.amount=EditorGUILayout.FloatField("Input change",sensitivity.amount);using(new EditorGUILayout.HorizontalScope()){foreach(float preset in new[]{-.1f,-.05f,.01f,.05f,.10f})if(GUILayout.Button(preset.ToString("+0%;-0%")))sensitivity.amount=preset;}
            string[] metrics=sensitivity.mode==SensitivityMode.Combat?new[]{"win_rate","p50_ttk","p90_ttk","mana_starvation","combat_dps"}:OptimizationMetricCatalog.All.Select(x=>x.Id).ToArray();sensitivity.metric=metrics[EditorGUILayout.Popup("Output metric",Mathf.Max(0,Array.IndexOf(metrics,sensitivity.metric)),metrics)];
            if(sensitivity.mode==SensitivityMode.Combat){EnsureCombat();combatRequest.fightCount=EditorGUILayout.IntField("Fights / variation",Mathf.Max(1,combatRequest.fightCount));combatRequest.seed=EditorGUILayout.LongField("Common seed",combatRequest.seed);}
            if(chosenStats==null||chosenStats.Length!=SensitivityAnalyzer.Catalog.Length){chosenStats=new bool[SensitivityAnalyzer.Catalog.Length];for(int i=0;i<chosenStats.Length;i++)chosenStats[i]=sensitivity.stats.Contains(SensitivityAnalyzer.Catalog[i]);}
            Heading("SELECT STATS");for(int i=0;i<SensitivityAnalyzer.Catalog.Length;i++){var stat=SensitivityAnalyzer.Catalog[i];chosenStats[i]=EditorGUILayout.ToggleLeft(stat+" ("+SensitivityAnalyzer.Unit(stat)+")",chosenStats[i]);}
            using(new EditorGUILayout.HorizontalScope())
            {
                if(GUILayout.Button("RUN SENSITIVITY",GUILayout.Height(30)))Run("Sensitivity",_=>{sensitivity.build=playerBuild.Clone();sensitivity.combat=JsonUtility.FromJson<CombatLabRequest>(JsonUtility.ToJson(combatRequest));sensitivity.stats=SensitivityAnalyzer.Catalog.Where((s,i)=>chosenStats[i]).ToList();sensitivityResult=SensitivityAnalyzer.Run(sensitivity,Progress("Stats"),()=>cancelled);});
                if(GUILayout.Button("PAIR ANALYSIS"))Run("Pair analysis",_=>{sensitivity.build=playerBuild.Clone();sensitivity.stats=SensitivityAnalyzer.Catalog.Where((s,i)=>chosenStats[i]).Take(12).ToList();sensitivityPairs=SensitivityAnalyzer.Pairs(sensitivity,sensitivity.stats,()=>cancelled);});
                if(GUILayout.Button("CURVE"))Run("Sensitivity curve",_=>{sensitivity.build=playerBuild.Clone();sensitivityCurve=SensitivityAnalyzer.Curve(sensitivity,curveStat,new[]{-.2f,-.1f,0f,.1f,.2f,.3f});});
            }
            curveStat=(StatTypes)EditorGUILayout.EnumPopup("Curve stat",curveStat);
            if(sensitivityResult!=null){if(sensitivityResult.Stale)EditorGUILayout.HelpBox("STALE — PRODUCTION DATA CHANGED",MessageType.Warning);Heading("RANKED IMPACT");impactSort=(ImpactSort)EditorGUILayout.EnumPopup("Sort",impactSort);var ordered=impactSort switch{ImpactSort.MostPositive=>sensitivityResult.rows.OrderByDescending(x=>x.absoluteDelta),ImpactSort.MostNegative=>sensitivityResult.rows.OrderBy(x=>x.absoluteDelta),_=>sensitivityResult.rows.OrderByDescending(x=>Math.Abs(x.absoluteDelta))};foreach(var x in ordered)EditorGUILayout.LabelField(x.stat.ToString(),$"{x.baseline:0.###} → {x.modified:0.###}  Δ{x.absoluteDelta:+0.###;-0.###;0}  {x.percentDelta:+0.##%;-0.##%;0%}  elasticity {x.elasticity:0.###}");if(GUILayout.Button("EXPORT CSV"))status=SaveAdvancedCsv("sensitivity","Stat,InputDelta,Baseline,Modified,AbsoluteDelta,PercentDelta,Elasticity",sensitivityResult.rows.Select(x=>$"{x.stat},{x.inputDelta:R},{x.baseline:R},{x.modified:R},{x.absoluteDelta:R},{x.percentDelta:R},{x.elasticity:R}"));}
            if(sensitivityCurve.Count>0){Heading("MULTI-POINT CURVE");foreach(var x in sensitivityCurve)EditorGUILayout.LabelField(x.x.ToString("+0%;-0%;0%"),x.mean.ToString("0.####"));var series=new List<CurveSeries>{new(){name=curveStat.ToString(),color=Color.cyan,points=sensitivityCurve}};chart.Draw(GUILayoutUtility.GetRect(200,260,GUILayout.ExpandWidth(true)),series,"Stat change",sensitivity.metric);if(GUILayout.Button("EXPORT CURVE PNG"))status=chart.ExportPng(series,"sensitivity_curve");}
            if(sensitivityPairs.Count>0){Heading("PAIR INTERACTIONS (observed − A − B)");foreach(var x in sensitivityPairs)EditorGUILayout.LabelField(x.a+" × "+x.b,x.interaction.ToString("+0.####;-0.####;0"));if(GUILayout.Button("EXPORT PAIRS CSV"))status=SaveAdvancedCsv("sensitivity_pairs","StatA,StatB,GainA,GainB,Observed,Interaction",sensitivityPairs.Select(x=>$"{x.a},{x.b},{x.gainA:R},{x.gainB:R},{x.observed:R},{x.interaction:R}"));}
            if(GUILayout.Button("SEND TO COMBAT LAB"))tab=Tab.CombatLab;
        }

