            using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("CAPTURE BEFORE",GUILayout.Height(30)))Run("Snapshot before",_=>beforeSnapshot=BalanceSnapshotService.Capture(balanceSuite,snapshotName,Progress("Suite"),()=>cancelled));if(GUILayout.Button("CAPTURE AFTER"))Run("Snapshot after",_=>{afterSnapshot=BalanceSnapshotService.Capture(balanceSuite,snapshotName,Progress("Suite"),()=>cancelled);if(beforeSnapshot!=null)differences=BalanceSnapshotService.Compare(beforeSnapshot,afterSnapshot,highlightPercent);});if(GUILayout.Button("COMPARE TO CURRENT")&&beforeSnapshot!=null)Run("Compare current",_=>{afterSnapshot=BalanceSnapshotService.Capture(beforeSnapshot.suite,"Current production",Progress("Suite"),()=>cancelled);differences=BalanceSnapshotService.Compare(beforeSnapshot,afterSnapshot,highlightPercent);});}
            using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("SAVE SUITE JSON"))status=WorkbenchExports.SaveJson("balance_suite",balanceSuite);if(GUILayout.Button("LOAD SUITE JSON")){string path=EditorUtility.OpenFilePanel("Load balance suite",WorkbenchExports.Root,"json");if(!string.IsNullOrEmpty(path))balanceSuite=JsonUtility.FromJson<BalanceSuite>(File.ReadAllText(path));}if(GUILayout.Button("LOAD BEFORE JSON")){string path=EditorUtility.OpenFilePanel("Load balance snapshot",WorkbenchExports.Root,"json");if(!string.IsNullOrEmpty(path))beforeSnapshot=JsonUtility.FromJson<BalanceSnapshot>(File.ReadAllText(path));}}
