        void BreakpointTab()
        {
            Heading("SCAN THEN REFINE");breakSource=(BreakSource)EditorGUILayout.EnumPopup("Source",breakSource);breakStart=EditorGUILayout.IntField("Start level",breakStart);breakEnd=EditorGUILayout.IntField("End level",breakEnd);breakStep=EditorGUILayout.IntField("Coarse step",breakStep);breakMetric=EditorGUILayout.TextField("Metric ID",breakMetric);breakThreshold=EditorGUILayout.DoubleField("Threshold",breakThreshold);breakOperator=(BreakpointOperator)EditorGUILayout.EnumPopup("Rule",breakOperator);breakAll=EditorGUILayout.Toggle("All crossings",breakAll);
            EditorGUILayout.HelpBox("Metric IDs: Combat win_rate/p50_ttk/p90_ttk/mana_starvation; Enemy dps_p50/life_p50; Drops gear_per_kill/currency_per_kill; Loot upgrades_per_100; Player uses the Player Build metric catalog.",MessageType.None);
            if(GUILayout.Button("FIND BREAKPOINT",GUILayout.Height(30)))Run("Breakpoint scan",_=>{EnsureCombat();breakResults=BreakpointFinder.Find(level=>BreakMetricAt(level),Mathf.Max(1,breakStart),Mathf.Max(breakStart,breakEnd),Mathf.Max(1,breakStep),breakThreshold,breakOperator,breakAll);foreach(var r in breakResults){r.metric=breakMetric;r.seed=combatRequest.seed;r.samples=breakSource==BreakSource.Combat?combatRequest.fightCount:breakSource==BreakSource.Drops?drop.sampleCount:1;r.fingerprint=ProductionBalanceAdapters.DataFingerprint();}});
            if(breakResults.Count>0){Heading("CROSSINGS");foreach(var r in breakResults)EditorGUILayout.LabelField("Level "+r.level,$"{r.before:0.####} → {r.at:0.####}; threshold {r.threshold:0.####}");var first=breakResults[0];var metricSeries=new CurveSeries{name=breakMetric,color=Color.cyan,points=first.curve.Select(x=>new CurvePoint{x=x.level,mean=x.value}).ToList()};var thresholdSeries=new CurveSeries{name="Threshold",color=Color.yellow,points=new(){new CurvePoint{x=breakStart,mean=breakThreshold},new CurvePoint{x=breakEnd,mean=breakThreshold}}};var plot=new List<CurveSeries>{metricSeries,thresholdSeries};chart.Draw(GUILayoutUtility.GetRect(200,280,GUILayout.ExpandWidth(true)),plot,"Level",breakMetric);using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("EXPORT CSV"))status=SaveAdvancedCsv("breakpoints","Level,Metric,Before,At,After,Threshold,Samples,Seed,Fingerprint",breakResults.Select(x=>$"{x.level},{x.metric},{x.before:R},{x.at:R},{x.after:R},{x.threshold:R},{x.samples},{x.seed},{x.fingerprint}"));if(GUILayout.Button("EXPORT PNG"))status=chart.ExportPng(plot,"breakpoints");}}
        }

        double BreakMetricAt(int level)
        {
            switch(breakSource)
            {
                case BreakSource.Combat:{var request=JsonUtility.FromJson<CombatLabRequest>(JsonUtility.ToJson(combatRequest));request.enemyLevel=level;var r=CombatLabAdapters.Batch(request);return breakMetric switch{"p50_ttk"=>r.duration.p50,"p90_ttk"=>r.duration.p90,"mana_starvation"=>r.manaStarvation.mean,_=>r.winRate};}
                case BreakSource.EnemyGear:{var r=ProductionBalanceAdapters.RunEnemies(new EnemyLabRequest{level=level,sampleCount=64,seed=combatRequest.seed,archetypeId=combatRequest.enemyArchetypeId,rarity=combatRequest.rarity});return breakMetric=="life_p50"?r.life.p50:r.dps.p50;}
                case BreakSource.Drops:{var request=JsonUtility.FromJson<DropLabRequest>(JsonUtility.ToJson(drop));request.level=level;var r=ProductionBalanceAdapters.RunDrops(request);return breakMetric=="gear_per_kill"?r.averageGearItems:r.averageCurrencyRolls;}
                case BreakSource.LootProgression:{var request=JsonUtility.FromJson<LootProgressionRequest>(JsonUtility.ToJson(lootRequest));request.combatLevel=level;request.kills=Mathf.Min(1000,request.kills);var r=LootProgressionAnalyzer.Run(request);return r.upgrades.Count*100.0/Math.Max(1,r.kills);}
                default:{var b=playerBuild.Clone();b.playerLevel=level;return OptimizationMetricCatalog.Get(breakMetric).Value(PlayerBuildEvaluator.Evaluate(b));}
            }
        }

