            if(lootResult==null)return;if(lootResult.Stale)EditorGUILayout.HelpBox("STALE — PRODUCTION DATA CHANGED",MessageType.Warning);
            EditorGUILayout.LabelField("Kills / drops / upgrades",$"{lootResult.kills} / {lootResult.drops} / {lootResult.upgrades.Count}");EditorGUILayout.LabelField("First upgrade kill",lootResult.firstUpgradeKill==0?"Not found":lootResult.firstUpgradeKill.ToString());EditorGUILayout.LabelField("Kills with ≥1 upgrade",$"{lootResult.killsWithUpgrade} ({lootResult.killsWithUpgrade/(double)Math.Max(1,lootResult.kills):P2})");EditorGUILayout.LabelField("Upgrades / 100 / 1,000 kills",$"{lootResult.upgrades.Count*100.0/Math.Max(1,lootResult.kills):0.##} / {lootResult.upgrades.Count*1000.0/Math.Max(1,lootResult.kills):0.##}");Summary("Kills between upgrades",lootResult.upgradeIntervals);Summary("Upgrade magnitude",lootResult.upgradeMagnitudes);Heading("PER SLOT");foreach(var g in lootResult.upgrades.GroupBy(x=>x.slot))EditorGUILayout.LabelField(g.Key,$"{g.Count()} upgrades · {lootResult.kills/(double)g.Count():0.##} kills / upgrade");Heading("PER RARITY");foreach(var g in lootResult.upgrades.GroupBy(x=>x.rarity))EditorGUILayout.LabelField(g.Key,g.Count().ToString());Heading("CURRENCY ACCUMULATION");foreach(var c in lootResult.currency)EditorGUILayout.LabelField(c.type.ToString(),$"{c.amount} total · {c.amount*100.0/Math.Max(1,lootResult.kills):0.##} / 100 kills · {c.amount/(double)Math.Max(1,lootResult.upgrades.Count):0.##} / upgrade");
            if(lootResult.upgrades.Count>0){var best=lootResult.upgrades.OrderByDescending(x=>x.magnitude).First();if(GUILayout.Button("INSPECT BEST DROPPED ITEM"))EditorUtility.DisplayDialog($"Upgrade at kill {best.kill}",best.item.Description+"\nObjective gain "+best.magnitude.ToString("0.####"),"Close");}
            if(GUILayout.Button("EXPORT PROGRESSION CSV"))status=SaveAdvancedCsv("loot_progression","Kill,Slot,Rarity,ObjectiveGain,Item",lootResult.upgrades.Select(x=>$"{x.kill},{x.slot},{x.rarity},{x.magnitude:R},{CsvQ(x.item.Description)}"));
        }

        void CraftingTab()
        {
            Heading("PRODUCTION CRAFTING TRIALS");if(GUILayout.Button("USE CURRENT BUILD WEAPON")){craftingRequest.item=playerBuild.equipment.FirstOrDefault(x=>x.slot==LootManager.GearType.Weapons);if(craftingRequest.item==null)status="No equipped weapon in current build.";}if(craftingRequest.item!=null)EditorGUILayout.HelpBox(craftingRequest.item.Description,MessageType.None);
            craftingRequest.trials=SampleCount(craftingRequest.trials,100000);craftingRequest.maxActions=EditorGUILayout.IntSlider("Max actions / attempt",craftingRequest.maxActions,1,1000);craftingRequest.seed=EditorGUILayout.LongField("Seed",craftingRequest.seed);craftingRequest.requiredMatches=EditorGUILayout.IntSlider("Required matching affixes",craftingRequest.requiredMatches,1,6);
            Heading("TARGET CONDITIONS");foreach(var t in craftingRequest.targets){using(new EditorGUILayout.HorizontalScope()){t.stat=(StatTypes)EditorGUILayout.EnumPopup(t.stat);t.maximumTier=EditorGUILayout.IntField("Tier ≤",t.maximumTier);t.minimumRoll=EditorGUILayout.FloatField("Roll ≥",t.minimumRoll);}}if(GUILayout.Button("ADD TARGET"))craftingRequest.targets.Add(new CraftTarget{stat=StatTypes.PhysDmg});
            Heading("ORDERED ACTION POLICY");foreach(var step in craftingRequest.policy){using(new EditorGUILayout.HorizontalScope()){step.action=(CraftingCurrencyType)EditorGUILayout.EnumPopup(step.action);step.repeats=EditorGUILayout.IntField("Repeats",step.repeats);}}if(GUILayout.Button("ADD ACTION"))craftingRequest.policy.Add(new CraftPolicyStep{action=CraftingCurrencyType.RerollRareModifier});EditorGUILayout.HelpBox("Only ordinary production gear-crafting operations are currently supported. A positive currency budget limits that action; zero means unlimited.",MessageType.Info);
            Heading("CURRENCY BUDGETS (0 = unlimited)");for(int i=0;i<craftingRequest.budgets.Count;i++){var budget=craftingRequest.budgets[i];using(new EditorGUILayout.HorizontalScope()){budget.type=(CraftingCurrencyType)EditorGUILayout.EnumPopup(budget.type);budget.amount=EditorGUILayout.IntField(budget.amount);}craftingRequest.budgets[i]=budget;}if(GUILayout.Button("ADD BUDGET"))craftingRequest.budgets.Add(new CurrencyStackData(CraftingCurrencyType.RerollRareModifier,10));
            using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("SAVE POLICY"))status=WorkbenchExports.SaveJson("craft_policy",craftingRequest);if(GUILayout.Button("LOAD POLICY")){string path=EditorUtility.OpenFilePanel("Load crafting policy",WorkbenchExports.Root,"json");if(!string.IsNullOrEmpty(path))craftingRequest=JsonUtility.FromJson<CraftingSimulationRequest>(File.ReadAllText(path));}if(GUILayout.Button("ADD POLICY TO COMPARISON"))craftPolicies.Add(JsonUtility.FromJson<CraftingSimulationRequest>(JsonUtility.ToJson(craftingRequest)));}
            if(craftPolicies.Count>=2&&GUILayout.Button("COMPARE SAVED POLICIES"))Run("Craft policy comparison",_=>{craftComparisons.Clear();foreach(var policy in craftPolicies.Take(5)){if(cancelled)break;craftComparisons.Add(CraftingSimulator.Run(policy,Progress("Policies"),()=>cancelled));}});
            if(craftComparisons.Count>0){Heading("POLICY COMPARISON");for(int i=0;i<craftComparisons.Count;i++){var r=craftComparisons[i];EditorGUILayout.LabelField("Policy "+(i+1),$"Success {(r.trials==0?0:r.successes/(double)r.trials):P1} · P50 actions {r.actions.p50:0.#} · P90 {r.actions.p90:0.#} · Potential failures {r.potentialFailures}");}}
            if(GUILayout.Button("RUN CRAFTING SIMULATOR",GUILayout.Height(30)))Run("Crafting trials",_=>craftingResult=CraftingSimulator.Run(craftingRequest,Progress("Crafts"),()=>cancelled));if(craftingResult==null)return;if(craftingResult.Stale)EditorGUILayout.HelpBox("STALE — PRODUCTION DATA CHANGED",MessageType.Warning);EditorGUILayout.LabelField("Success rate",craftingResult.trials==0?"n/a":(craftingResult.successes/(double)craftingResult.trials).ToString("P2"));EditorGUILayout.LabelField("Potential / budget failures",$"{craftingResult.potentialFailures} / {craftingResult.budgetFailures}");Summary("Action count",craftingResult.actions);Summary("Final target matches",craftingResult.finalMatches);foreach(var c in craftingResult.costs)EditorGUILayout.LabelField(c.currency.ToString(),$"Mean {c.mean:0.##} · P50 {c.p50:0.##} · P90 {c.p90:0.##} · P95 {c.p95:0.##} · P99 {c.p99:0.##}");if(craftingResult.replay!=null){Heading("REPLAY ATTEMPT");foreach(var step in craftingResult.replay.trace)EditorGUILayout.LabelField($"{step.number}. {step.action}",$"Potential {step.potentialBefore} → {step.potentialAfter}");if(GUILayout.Button("EXPORT TRACE JSON"))status=WorkbenchExports.SaveJson("craft_trace",craftingResult.replay);}
            if(GUILayout.Button("EXPORT CRAFTING CSV"))status=SaveAdvancedCsv("crafting_result","Trials,Successes,PotentialFailures,BudgetFailures,MedianActions,P90Actions",new[]{$"{craftingResult.trials},{craftingResult.successes},{craftingResult.potentialFailures},{craftingResult.budgetFailures},{craftingResult.actions.p50:R},{craftingResult.actions.p90:R}"});
        }

        static string CsvQ(string value)=>"\""+(value??"").Replace("\"","\"\"")+"\"";
        static string SaveAdvancedCsv(string name,string header,IEnumerable<string> rows){Directory.CreateDirectory(WorkbenchExports.Root);string path=Path.Combine(WorkbenchExports.Root,name+"_"+DateTime.UtcNow.ToString("yyyyMMdd_HHmmss")+".csv");File.WriteAllLines(path,new[]{header}.Concat(rows));AssetDatabase.Refresh();return path;}
    }
}
